def c(ref,val,style=0,formula=None):
    s=f' s="{style}"' if style else ''
    if formula is not None:return f'<c r="{ref}"{s}><f>{escape(formula)}</f><v>{val}</v></c>'
    if isinstance(val,(int,float)):return f'<c r="{ref}"{s}><v>{val}</v></c>'
    return f'<c r="{ref}" t="inlineStr"{s}><is><t>{escape(str(val))}</t></is></c>'
def sh(rows,extra=''):
    body=''.join('<row r="%d">%s</row>'%(ri,''.join(c(*x) for x in cs)) for ri,cs in rows)
    return f'''<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews><sheetData>{body}</sheetData>{extra}</worksheet>'''

F['xl/worksheets/sheet1.xml']=sh([(1,[('A1','JPN Gestão Fácil v0.3 — CANDIDATA',1)]),(2,[('A2','Dados fictícios. Financeiro vazio. Compatibilidade física ainda pendente.')]),(3,[('A3','REPOR é alerta operacional e não autoriza compra.')])])
