F['xl/charts/chart1.xml']='''<?xml version="1.0" encoding="UTF-8" standalone="yes"?><c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart><c:title><c:tx><c:rich><a:bodyPr xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"/><a:lstStyle xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"/><a:p xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:r><a:t>Situação das vendas</a:t></a:r></a:p></c:rich></c:tx></c:title><c:plotArea><c:layout/><c:barChart><c:barDir val="col"/><c:grouping val="clustered"/><c:ser><c:idx val="0"/><c:order val="0"/><c:cat><c:strRef><c:f>Dashboard!$A$4:$A$5</c:f></c:strRef></c:cat><c:val><c:numRef><c:f>Dashboard!$B$4:$B$5</c:f></c:numRef></c:val></c:ser><c:axId val="10"/><c:axId val="20"/></c:barChart><c:catAx><c:axId val="10"/><c:crossAx val="20"/></c:catAx><c:valAx><c:axId val="20"/><c:crossAx val="10"/></c:valAx></c:plotArea></c:chart></c:chartSpace>'''
H={3:['ID','Nome/Empresa','Contato','Canal','Etapa','Responsável','Próxima ação','Data da próxima ação','Observações','Atualização'],4:['ID','Data','Cliente','Produto/Serviço','Etapa','Responsável','Quantidade','Valor unitário','Valor total','Próxima ação','Observações'],5:['ID','Tarefa','Categoria','Responsável','Prioridade','Status','Início','Prazo','Próximo passo','Observações'],6:['Código','Item','Categoria','Unidade','Estoque atual','Estoque mínimo','Reposição?','Fornecedor','Observações'],7:['ID','Data','Tipo','Descrição','Categoria','Centro/Projeto','Valor','Status','Vencimento','Observações']}
D={3:[['C001','Cliente Exemplo 1','','WhatsApp','Qualificado'],['C002','Cliente Exemplo 2','','Indicação','Novo'],['C003','Cliente Exemplo 3','','Site','Ativo']],4:[['V001','2026-09-01','Cliente Exemplo 1','Serviço A','Aberta','Equipe',1,0],['V002','2026-09-02','Cliente Exemplo 2','Serviço B','Aberta','Equipe',2,0],['V003','2026-09-03','Cliente Exemplo 3','Serviço C','Ganha','Equipe',1,0]],5:[['T001','Retornar cliente','Comercial','Equipe','Alta','Pendente','2026-09-01','2099-12-31'],['T002','Revisar proposta','Comercial','Equipe','Média','Pendente','2026-09-02','2099-12-31']],6:[['E001','Item Exemplo 1','Geral','un',1,2],['E002','Item Exemplo 2','Geral','un',5,2]],7:[]}
for sn in range(3,8):
    rr=[(1,[(chr(65+i)+'1',h,1) for i,h in enumerate(H[sn])])]
    for rix,row in enumerate(D[sn],2):
        cells=[(chr(65+i)+str(rix),v) for i,v in enumerate(row)]
        if sn==4:cells.append(('I'+str(rix),0,0,f'IF(OR(G{rix}="",H{rix}=""),"",G{rix}*H{rix})'))
        if sn==6:cells.append(('G'+str(rix),'REPOR' if row[4]<=row[5] else 'OK',0,f'IF(OR(B{rix}="",E{rix}="",F{rix}=""),"",IF(E{rix}<=F{rix},"REPOR","OK"))'))
        rr.append((rix,cells))
    extra=f'<autoFilter ref="A1:{chr(64+len(H[sn]))}{max(1,len(rr))}"/>'
    if sn in [3,4,5,7]:extra+='<dataValidations count="1"><dataValidation type="list" sqref="A2:A100"><formula1>Listas!$A$2:$A$10</formula1></dataValidation></dataValidations>'
